CREATE TABLE `eventos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `titulo` varchar(191) NOT NULL,
  `grado` varchar(191) NOT NULL,
  `curricular` varchar(191) NOT NULL,
  `modalidad_id` bigint(20) unsigned NOT NULL,
  `lugar_id` bigint(20) unsigned DEFAULT NULL,
  `tipo_id` bigint(20) unsigned NOT NULL,
  `programa_id` bigint(20) unsigned DEFAULT NULL,
  `responsables` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `colaboradores` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `destinatarios` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `carga_horaria` int(11) DEFAULT NULL,
  `fecha_inicio` datetime DEFAULT NULL,
  `fecha_fin` datetime DEFAULT NULL,
  `resolucion` varchar(191) DEFAULT NULL,
  `enlace_inscripcion` varchar(191) DEFAULT NULL,
  `imagen` varchar(191) DEFAULT NULL,
  `observaciones` longtext DEFAULT NULL,
  `active` tinyint(1) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `eventos_lugar_id_foreign` (`lugar_id`),
  KEY `eventos_modalidad_id_foreign` (`modalidad_id`),
  KEY `eventos_tipo_id_foreign` (`tipo_id`),
  CONSTRAINT `eventos_lugar_id_foreign` FOREIGN KEY (`lugar_id`) REFERENCES `lugares` (`id`),
  CONSTRAINT `eventos_modalidad_id_foreign` FOREIGN KEY (`modalidad_id`) REFERENCES `modalidades` (`id`),
  CONSTRAINT `eventos_tipo_id_foreign` FOREIGN KEY (`tipo_id`) REFERENCES `tipos_eventos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=399 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

