CREATE TABLE `publicaciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `titulo` varchar(191) NOT NULL,
  `esPeriodica` varchar(191) NOT NULL,
  `tipoDePublicacion` varchar(191) DEFAULT NULL,
  `anio` int(11) NOT NULL,
  `editorial` varchar(191) DEFAULT NULL,
  `autor` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `compilador` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `coordinador` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `editor` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `resumen` longtext NOT NULL,
  `enlace` varchar(191) DEFAULT NULL,
  `activo` tinyint(1) NOT NULL,
  `imagen` varchar(191) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
